{
  "schema_version": 1,
  "template_id": "store-operations-coordinator",
  "template_version": 1,
  "checks": [
    {
      "id": "identity",
      "title": "Confirm the Shopify role",
      "instructions": "Confirm whether Store Operations Coordinator is this Crew's primary role or a supporting capability. Preserve an existing Crew identity and name the merchant owner."
    },
    {
      "id": "skill",
      "title": "Verify the selected skill",
      "instructions": "Confirm skills/store-operations-coordinator/SKILL.md exists and store-operations-coordinator is selected for this Crew."
    },
    {
      "id": "scope",
      "title": "Set store and job scope",
      "instructions": "Record exact store, market, owner, time window, first job, and authorized data scope. Minimum input: Shopify store and order scope, authorized order or fulfillment records, service policy, inventory source if relevant, and operations owner."
    },
    {
      "id": "access",
      "title": "Test source access",
      "instructions": "Read one scoped Order with its line items and payment state, then its FulfillmentOrders/fulfillments and a matching warehouse or carrier record. Record the Shopify IDs, external ID, observed times, and which source owns each state. A missing external match stays unknown. Record exact IDs, freshness, and access gaps. Shopify Admin, warehouse or fulfillment provider, shipping tracker, helpdesk, and approved team channel; a bounded export supports the first read-only queue. A provider name is not a connection."
    },
    {
      "id": "policy",
      "title": "Verify domain rules and owner",
      "instructions": "Confirm the merchant's policy, owner, and unknown-state treatment. Classify at the affected line-item/fulfillment level; an order can have partial or split fulfillment. A shipping label or tracking number is not proof of carrier acceptance or delivery. Escalate a missed service deadline using the merchant policy and a named owner. If the customer requests money or a return, hand over the exact case and source references; do not turn the operations queue into a refund decision. Do not join stores or customers by name alone."
    },
    {
      "id": "first_result",
      "title": "Produce the first result",
      "instructions": "Use actual authorized evidence to produce An order exception queue with exact order and fulfillment IDs, current state, evidence, owner, deadline, and proposed next action. Cite order, fulfillment, tracking, and support record IDs with observation times. A label-created shipment is not proof of delivery. Setup proof: Show one real order with a line-level fulfillment join, a deliberately missing or stale external tracking state, the merchant service deadline, and the named owner decision. Fictional examples do not complete this check."
    },
    {
      "id": "review",
      "title": "Review the result and next action",
      "instructions": "Show the sourced result, unresolved facts, policy and money checks, proposed next action, approval owner, and exact evidence needed for closure. Record the owner decision."
    },
    {
      "id": "action_route",
      "title": "Choose customer and store action routes",
      "optional": true,
      "instructions": "Choose read-only chat or separately authorized store writes, refunds, labels, and messages. Read-only chat completes this decision. Do not cancel, fulfill, edit inventory, issue a refund, or contact a customer without an authorized action route and exact owner decision."
    },
    {
      "id": "recurrence",
      "title": "Choose recurrence and repeat behavior",
      "optional": true,
      "instructions": "Choose manual-only or a reviewed schedule, authenticated trigger, function, or Automation. Manual-only completes this decision. Re-read the same order and fulfillment IDs before another action; compare new versus resolved exceptions and check prior contact or refund state to avoid duplicates. Test a configured route before activation."
    }
  ],
  "completed_steps": []
}

