files.templates/replenishment-planner/TEMPLATE:
{
  "schema_version": 1,
  "template_id": "replenishment-planner",
  "template_version": 1,
  "checks": [
    {
      "id": "identity",
      "title": "Confirm the Shopify role",
      "instructions": "Confirm whether Replenishment Planner is this Crew's primary role or a supporting capability. Preserve an existing Crew identity and name the merchant owner."
    },
    {
      "id": "skill",
      "title": "Verify the selected skill",
      "instructions": "Confirm skills/replenishment-planner/SKILL.md exists and replenishment-planner is selected for this Crew."
    },
    {
      "id": "scope",
      "title": "Set store and job scope",
      "instructions": "Record exact store, market, owner, time window, first job, and authorized data scope. Minimum input: Store, market, variant, inventory item and destination location IDs; authorized inventory and demand records; supplier SKU, lead time, MOQ/case pack, unit cost and currency; procurement owner."
    },
    {
      "id": "access",
      "title": "Test source access",
      "instructions": "Read one authorized InventoryLevel by exact item/location ID, one same-variant demand extract, one supplier terms record, and current open PO/transfer records. Confirm which source owns lead time and incoming quantity. Record exact IDs, freshness, and access gaps. Shopify InventoryLevel, Shopify purchase orders and linked transfers, supplier portal or ERP, and sales history; bounded exports can support a read-only first proposal without purchase-order access. A provider name is not a connection."
    },
    {
      "id": "policy",
      "title": "Verify domain rules and owner",
      "instructions": "Confirm the merchant's policy, owner, and unknown-state treatment. Shopify InventoryLevel is per item and location. Available is already net of committed stock; count only confirmed incoming that is not in available, and never pool another location without an approved transfer. Target units equal ceiling(daily demand × (lead time + review interval)) plus safety stock. Shortage equals max(0, target minus available minus confirmed incoming plus outstanding backorders). Round a positive order to the case pack and MOQ; show every assumption. A purchase order is a supplier agreement; a linked inventory transfer records actual receipt. Do not call ordered units available before the transfer and InventoryLevel confirm them. Do not join stores or customers by name alone."
    },
    {
      "id": "first_result",
      "title": "Produce the first result",
      "instructions": "Use actual authorized evidence to produce A sourced reorder or defer decision with exact inventory item and location, demand basis, incoming stock, supplier terms, rounded quantity, cost, owner and next evidence. Cite InventoryLevel, demand export, supplier terms, open PO/transfer and budget sources with timestamps and exact IDs. A PO marked ordered is not proof that units were received. Setup proof: Recompute one real item/location proposal from current inventory, demand, incoming and supplier terms; show a missing-data case, an open-PO duplicate check, and a procurement owner decision. Fictional examples do not complete this check."
    },
    {
      "id": "review",
      "title": "Review the result and next action",
      "instructions": "Show the recomputed target, shortage, case-pack/MOQ quantity, total cost, supplier and budget evidence, missing assumptions, procurement owner decision, and separate proof required for a PO or received stock."
    },
    {
      "id": "action_route",
      "title": "Choose procurement and inventory action routes",
      "optional": true,
      "instructions": "Choose read-only chat or a separately authorized purchase-order and inventory-transfer route. Read-only chat completes this decision. A PO draft, supplier confirmation, transfer receipt, and available stock are separate states. Do not create or submit a purchase order, promise availability, move or receive stock, or pay a supplier without a current-state recheck, procurement approval and an authorized provider route."
    },
    {
      "id": "recurrence",
      "title": "Choose recurrence and repeat behavior",
      "optional": true,
      "instructions": "Choose manual-only or a reviewed schedule, authenticated trigger, function, or Automation. Manual-only completes this decision. Re-read inventory, incoming transfers, open POs and supplier terms before another proposal; use a stable item-location-supplier-window key and net out prior approved orders to avoid double ordering. Test a configured route before activation."
    }
  ],
  "completed_steps": []
}
